window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cf14889991042812"]={"versions": [{"id": "FIG-cf14889991042812", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Wirkkettendiagramm (Timing Analysis / End-to-End Timing Requirement) eines aktiven Lenksystems (Active Steering Project). Das Schaubild veranschaulicht eine verteilte Regelkette über mehrere Steuergeräte und Bussysteme zur Einhaltung einer maximal zulässigen Gesamtlatenz.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst:</p>\n<ul class=\"fig-list\">\n<li>Sensoren und Aktoren: <code>yaw rate sensor</code> (Gierratensensor), Lenkrad mit integriertem <code>angle sensor</code> (Lenkwinkelsensor) und <code>electric motor</code> (Stellmotor).</li>\n<li>Steuergeräte (ECUs): <code>ICM</code> (Integrated Chassis Management) und <code>ASA</code> (Active Steering Actuator / Aktive Lenkung).</li>\n<li>Netzwerke/Busverbindungen:</li>\n<li>CAN-Bus zwischen <code>yaw rate sensor</code> und <code>ICM</code></li>\n<li>Direkte Sensoranbindung zwischen Lenkrad-<code>angle sensor</code> und <code>ICM</code></li>\n<li>FlexRay-Verbindung zwischen <code>ICM</code> und <code>ASA</code></li>\n<li>CAN-Bus zwischen <code>electric motor</code> und <code>ASA</code></li>\n<li>Signale/Größen:</li>\n<li>$T_1$: <code>raw yaw rate</code></li>\n<li>$T_2$: interne Verarbeitung im <code>ICM</code></li>\n<li>$T_3$: <code>required \\Delta angle</code> (Soll-Zusatzwinkel über FlexRay)</li>\n<li>$T_4$: interne Verarbeitung im <code>ASA</code></li>\n<li>$T_5$: <code>motor control</code> (Ansteuerung Stellmotor über CAN)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Steuer- und Regelkette beschreibt eine geschlossene Wirkkette:</p>\n<ol class=\"fig-list\">\n<li>Erfassung der Rohgierrate durch den <code>yaw rate sensor</code> und Übertragung an das <code>ICM</code> über CAN ($T_1$).</li>\n<li>Verarbeitung des Gierratensignals und des Lenkwinkels im Steuergerät <code>ICM</code> ($T_2$).</li>\n<li>Übertragung des berechneten Stellwinkels (<code>required \\Delta angle</code>) über den FlexRay-Bus an das Steuergerät <code>ASA</code> ($T_3$).</li>\n<li>Berechnung der Motoransteuerung innerhalb des Steuergeräts <code>ASA</code> ($T_4$).</li>\n<li>Ausgabe des Stellbefehls (<code>motor control</code>) über CAN an den <code>electric motor</code> am Lenkrad ($T_5$).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine harte End-to-End-Timing-Anforderung für die aktive Lenkung:</p>\n<p class=\"fig-p\">$$T_1 + T_2 + T_3 + T_4 + T_5 < 30\\,\\text{ms}$$</p>\n<p class=\"fig-p\">Die Summe aus den Kommunikationszeiten auf den Bussystemen (CAN, FlexRay) und den internen Verarbeitungs- bzw. Tasklaufzeiten auf den beteiligten Steuergeräten (<code>ICM</code>, <code>ASA</code>) darf 30 ms nicht überschreiten. Entwickler müssen bei der Timing-Analyse Worst-Case Execution Times (WCET) sowie Übertragungs- und Pufferlatenzen über heterogene Bussysteme (CAN/FlexRay-Gateway- und Buszykluszeiten) berücksichtigen.</p>"}, {"id": "FIG-bcd2bb6939bf9807", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Wirkkettendiagramm (Timing Analysis / End-to-End Timing Requirement) eines aktiven Lenksystems (Active Steering Project). Das Schaubild veranschaulicht eine verteilte Regelkette über mehrere Steuergeräte und Bussysteme zur Einhaltung einer maximal zulässigen Gesamtlatenz.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst:</p>\n<ul class=\"fig-list\">\n<li>Sensoren und Aktoren: <code>yaw rate sensor</code> (Gierratensensor), Lenkrad mit integriertem <code>angle sensor</code> (Lenkwinkelsensor) und <code>electric motor</code> (Stellmotor).</li>\n<li>Steuergeräte (ECUs): <code>ICM</code> (Integrated Chassis Management) und <code>ASA</code> (Active Steering Actuator / Aktive Lenkung).</li>\n<li>Netzwerke/Busverbindungen:</li>\n<li>CAN-Bus zwischen <code>yaw rate sensor</code> und <code>ICM</code></li>\n<li>Direkte Sensoranbindung zwischen Lenkrad-<code>angle sensor</code> und <code>ICM</code></li>\n<li>FlexRay-Verbindung zwischen <code>ICM</code> und <code>ASA</code></li>\n<li>CAN-Bus zwischen <code>electric motor</code> und <code>ASA</code></li>\n<li>Signale/Größen:</li>\n<li>$T_1$: <code>raw yaw rate</code></li>\n<li>$T_2$: interne Verarbeitung im <code>ICM</code></li>\n<li>$T_3$: <code>required \\Delta angle</code> (Soll-Zusatzwinkel über FlexRay)</li>\n<li>$T_4$: interne Verarbeitung im <code>ASA</code></li>\n<li>$T_5$: <code>motor control</code> (Ansteuerung Stellmotor über CAN)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Steuer- und Regelkette beschreibt eine geschlossene Wirkkette:</p>\n<ol class=\"fig-list\">\n<li>Erfassung der Rohgierrate durch den <code>yaw rate sensor</code> und Übertragung an das <code>ICM</code> über CAN ($T_1$).</li>\n<li>Verarbeitung des Gierratensignals und des Lenkwinkels im Steuergerät <code>ICM</code> ($T_2$).</li>\n<li>Übertragung des berechneten Stellwinkels (<code>required \\Delta angle</code>) über den FlexRay-Bus an das Steuergerät <code>ASA</code> ($T_3$).</li>\n<li>Berechnung der Motoransteuerung innerhalb des Steuergeräts <code>ASA</code> ($T_4$).</li>\n<li>Ausgabe des Stellbefehls (<code>motor control</code>) über CAN an den <code>electric motor</code> am Lenkrad ($T_5$).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine harte End-to-End-Timing-Anforderung für die aktive Lenkung:</p>\n<p class=\"fig-p\">$$T_1 + T_2 + T_3 + T_4 + T_5 < 30\\,\\text{ms}$$</p>\n<p class=\"fig-p\">Die Summe aus den Kommunikationszeiten auf den Bussystemen (CAN, FlexRay) und den internen Verarbeitungs- bzw. Tasklaufzeiten auf den beteiligten Steuergeräten (<code>ICM</code>, <code>ASA</code>) darf 30 ms nicht überschreiten. Entwickler müssen bei der Timing-Analyse Worst-Case Execution Times (WCET) sowie Übertragungs- und Pufferlatenzen über heterogene Bussysteme (CAN/FlexRay-Gateway- und Buszykluszeiten) berücksichtigen.</p>"}], "trans": [{"from": "FIG-cf14889991042812", "to": "FIG-bcd2bb6939bf9807", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
